    int cMinusB = aSquared / s;
    int bNumerator = s - cMinusB;
    int cNumerator = s + cMinusB;
    if (bNumerator <= 2 * a || bNumerator % 2 != 0 || cNumerator % 2 != 0) {
        continue;
    }
    int b = bNumerator / 2;
